CREATE     PROCEDURE [synapse_fo].[usp_Insert_DIMENSIONATTRIBUTE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:42
	Description: Insert stored procedure for DIMENSIONATTRIBUTE from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[DIMENSIONATTRIBUTE]
	(
		[BACKINGENTITYKEYFIELDID],
		[BACKINGENTITYKEYFIELDNAME],
		[BACKINGENTITYTABLEID],
		[BACKINGENTITYTABLENAME],
		[BACKINGENTITYTYPE],
		[BACKINGENTITYVALUEFIELDID],
		[BACKINGENTITYVALUEFIELDNAME],
		[BALANCINGDIMENSION_PSN],
		[COPYVALUESONCREATE],
		[CREATEDBY],
		[CREATEDDATETIME],
		[DataLakeModified_DateTime],
		[DIMENSIONKEYCOLUMNNAME],
		[DIMENSIONVALUECOLUMNNAME],
		--[FileName],
		[GIVEDERIVEDDIMENSIONSPRECEDENCE],
		[HASHKEY],
		[ISBALANCING_PSN],
		[KEYATTRIBUTE],
		[LastProcessedChange_DateTime],
		--[LSN],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[NAME],
		[NAMEATTRIBUTE],
		[PARTITION],
		[RECID],
		[RECVERSION],
		[REPORTCOLUMNNAME],
		--[SysRowId],
		[TRANSLATIONKEYFIELDID],
		[TRANSLATIONKEYFIELDNAME],
		[TRANSLATIONLANGUAGEIDFIELDID],
		[TRANSLATIONLANGUAGEIDFIELDNAME],
		[TRANSLATIONNAMEFIELDID],
		[TRANSLATIONNAMEFIELDNAME],
		[TRANSLATIONTABLEID],
		[TRANSLATIONTABLENAME],
		[TRANSLATIONVIEWID],
		[TRANSLATIONVIEWKEYFIELDID],
		[TRANSLATIONVIEWKEYFIELDNAME],
		[TRANSLATIONVIEWLANGUAGEIDFIELDID],
		[TRANSLATIONVIEWLANGUAGEIDFIELDNAME],
		[TRANSLATIONVIEWNAME],
		[TRANSLATIONVIEWNAMEFIELDID],
		[TRANSLATIONVIEWNAMEFIELDNAME],
		[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDID],
		[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDNAME],
		[TRANSLATIONVIEWTRANSLATEDNAMEFIELDID],
		[TRANSLATIONVIEWTRANSLATEDNAMEFIELDNAME],
		[TRANSLATIONVIEWVALUEFIELDID],
		[TRANSLATIONVIEWVALUEFIELDNAME],
		[TYPE],
		[USETRANSLATIONNAMEMETHOD],
		[VALUEATTRIBUTE],
		[VIEWNAME]
	)
	SELECT 
		stg.[BACKINGENTITYKEYFIELDID],
		stg.[BACKINGENTITYKEYFIELDNAME],
		stg.[BACKINGENTITYTABLEID],
		stg.[BACKINGENTITYTABLENAME],
		stg.[BACKINGENTITYTYPE],
		stg.[BACKINGENTITYVALUEFIELDID],
		stg.[BACKINGENTITYVALUEFIELDNAME],
		stg.[BALANCINGDIMENSION_PSN],
		stg.[COPYVALUESONCREATE],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[DataLakeModified_DateTime],
		stg.[DIMENSIONKEYCOLUMNNAME],
		stg.[DIMENSIONVALUECOLUMNNAME],
		--stg.--[FileName],
		stg.[GIVEDERIVEDDIMENSIONSPRECEDENCE],
		stg.[HASHKEY],
		stg.[ISBALANCING_PSN],
		stg.[KEYATTRIBUTE],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[NAME],
		stg.[NAMEATTRIBUTE],
		stg.[PARTITION],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REPORTCOLUMNNAME],
		--stg.--[SysRowId],
		stg.[TRANSLATIONKEYFIELDID],
		stg.[TRANSLATIONKEYFIELDNAME],
		stg.[TRANSLATIONLANGUAGEIDFIELDID],
		stg.[TRANSLATIONLANGUAGEIDFIELDNAME],
		stg.[TRANSLATIONNAMEFIELDID],
		stg.[TRANSLATIONNAMEFIELDNAME],
		stg.[TRANSLATIONTABLEID],
		stg.[TRANSLATIONTABLENAME],
		stg.[TRANSLATIONVIEWID],
		stg.[TRANSLATIONVIEWKEYFIELDID],
		stg.[TRANSLATIONVIEWKEYFIELDNAME],
		stg.[TRANSLATIONVIEWLANGUAGEIDFIELDID],
		stg.[TRANSLATIONVIEWLANGUAGEIDFIELDNAME],
		stg.[TRANSLATIONVIEWNAME],
		stg.[TRANSLATIONVIEWNAMEFIELDID],
		stg.[TRANSLATIONVIEWNAMEFIELDNAME],
		stg.[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDID],
		stg.[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDNAME],
		stg.[TRANSLATIONVIEWTRANSLATEDNAMEFIELDID],
		stg.[TRANSLATIONVIEWTRANSLATEDNAMEFIELDNAME],
		stg.[TRANSLATIONVIEWVALUEFIELDID],
		stg.[TRANSLATIONVIEWVALUEFIELDNAME],
		stg.[TYPE],
		stg.[USETRANSLATIONNAMEMETHOD],
		stg.[VALUEATTRIBUTE],
		stg.[VIEWNAME]	
	FROM [staging_fo].[DIMENSIONATTRIBUTE] stg
		LEFT JOIN [synapse_fo].[DIMENSIONATTRIBUTE] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
